mapper.select:
SELECT /* LGVPAY00005.retrieveCalSetEmpList */ em.employee_number AS employee_no , em.full_name_english AS employee_name , em.grade AS grade_code , em.grade_title ,(SELECT lgvhr_common_pkg.decode_lookup('IF_VIETNAM_GRADE_TITLE', em.grade_title, NULL, #{USER_SESSION.languageCode}) FROM DUAL) as grade_title_name , em.grade_type AS emp_category_name , em.organization_id , um.default_org_id , em.org_name_local AS organization_name , em.attribute10 AS shift_type_code , em.job_family||'.'||em.job_group||'.'||em.job_detail AS work_type_name , em.assignment_category AS employment_category_code /* 재량권 조회시 사용 */ ,(SELECT lgvhr_common_pkg.decode_lookup('LGVHR_SHIFT_TYPE_CODE', em.attribute10, NULL, #{USER_SESSION.languageCode}) FROM DUAL) AS shift_type_name , um.application_user_id , um.mail_addr , cv.organization_id AS operating_unit_id , TO_CHAR(em.date_hire_subsidiary, 'DD/MM/YYYY') as date_hire_subsidiary , TO_CHAR(em.date_retire, 'DD/MM/YYYY') as date_retire FROM tb_pay_calc_set_target_per_n cstp , emp_master em , lgcom_user_m um , lgcom_company_v cv WHERE cstp.payroll_calculation_set_id = #{calculationSetId} AND em.employee_number = cstp.employee_no AND um.user_name = em.employee_number AND cv.short_code = em.subsidiary_code
AND cstp.employee_no = #{employeeNo}
ORDER BY em.employee_number asc

SELECT /* LGVPAY00005.createDirectCSVDownloadData */ employee_no , employee_name , grade_code , grade_title_name , organization_name , emp_category_name , work_type_name , date_hire_subsidiary , date_retire FROM ( SELECT '1' gubun , 'Employee No' AS EMPLOYEE_NO , 'Employee Name' AS EMPLOYEE_NAME , 'Grade' AS GRADE_CODE , 'Title' AS GRADE_TITLE_NAME , 'Organization Name' AS ORGANIZATION_NAME , 'Emp. Category' AS EMP_CATEGORY_NAME , 'Work Type' AS WORK_TYPE_NAME , 'Hire Date' AS DATE_HIRE_SUBSIDIARY , 'Resignation Date' AS DATE_RETIRE FROM DUAL UNION ALL SELECT '2' gubun , em.employee_number AS employee_no , em.full_name_english AS employee_name , em.grade AS grade_code ,(SELECT lgvhr_common_pkg.decode_lookup('IF_VIETNAM_GRADE_TITLE', em.grade_title, NULL, #{USER_SESSION.languageCode}) FROM DUAL) as grade_title_name , em.org_name_local AS organization_name , em.grade_type AS emp_category_name , em.job_family||'.'||em.job_group||'.'||em.job_detail AS work_type_name , TO_CHAR(em.date_hire_subsidiary, 'DD/MM/YYYY') as date_hire_subsidiary , TO_CHAR(em.date_retire, 'DD/MM/YYYY') as date_retire FROM tb_pay_calc_set_target_per_n cstp , emp_master em , lgcom_user_m um , lgcom_company_v cv WHERE cstp.payroll_calculation_set_id = #{calculationSetId} AND em.employee_number = cstp.employee_no AND um.user_name = em.employee_number AND cv.short_code = em.subsidiary_code
AND cstp.employee_no = #{employeeNo}
AND UPPER(em.full_name_local) like '%' || UPPER(#{employeeName}) || '%'
) ORDER BY employee_no asc

SELECT /* LGVPAY00005.retrieveRegCalEmpChk */
    count(1) as cnt
FROM tb_pay_calc_set_target_per_n
WHERE payroll_calculation_set_id = #{calculationSetId}
AND employee_no = #{employeeNo}

mapper.update:
DELETE FROM tb_pay_calc_set_target_per_n
WHERE payroll_calculation_set_id = #{calculationSetId}
AND employee_no = #{employeeNo}
